-- The notice and the front matter that every page generated by `hecate.doc` for a project carries, and the one test
-- that tells a generated page from a hand-written one. Shared by `hecate.doc.project` (the configuration reference),
-- the generation of the documentation of a project (the licences page), and the code reference (`hecate.doc.reference`,
-- `hecate.doc.reference_site`): the replacement and the removal of a page depend on this test alone.
global <const> require, tostring, type, pcall

local front_matter = require("hecate.doc.front_matter")
local text_helpers = require("hecate.doc.internal.text")

local M = {}

--- The notice written at the top of every generated project page.
M.GENERATED = "<!-- Generated by hecate.doc. Do not edit; change the project and build again. -->"

--- What every notice starts with (the code reference words its own notice after it).
M.NOTICE_PREFIX = "<!-- Generated by hecate.doc"

--- Tells whether a page was written by `hecate.doc`: its front matter says `generated: true`, or the first line of the
--- body is a notice (`M.NOTICE_PREFIX` at the start of the line, a closing ` -->` at its end). A notice quoted further
--- down (in a paragraph, a code block, an indented block) does not count: a hand-written page that explains the
--- notice is never replaced or removed. A malformed front matter is not ours either.
---@param text any  anything is accepted: a value that is not a string is not generated
---@return boolean
function M.is_generated(text)
  if type(text) ~= "string" then return false end
  local ok, meta, body = pcall(front_matter.parse, text)
  if not ok then return false end
  if meta.generated == true then return true end
  for line in body:gmatch("[^\n]+") do
    if not line:find("^%s*$") then
      return line:sub(1, #M.NOTICE_PREFIX) == M.NOTICE_PREFIX and line:find(" %-%->%s*$") ~= nil
    end
  end
  return false
end

-- A YAML double-quoted scalar (YAML 1.2.2, 7.3.1) on one line. Control characters become a space: the
-- front matter parser of this package accepts only the escapes `\\`, `\"`, `\n` and `\t`.
local function yaml_quote(text)
  text = tostring(text):gsub("%c", " "):gsub("\\", "\\\\"):gsub('"', '\\"')
  return '"' .. text .. '"'
end

--- The lines that open a generated page: front matter, the notice and the title.
---@param title string
---@param description? string  defaults to the title
---@param order integer
---@param audience hecate.doc.Audience
---@return string[] lines
function M.front(title, description, order, audience)
  return { "---", "description: " .. yaml_quote(description or title),
    "order: " .. tostring(order), "audience: " .. audience, "generated: true", "---", "", M.GENERATED, "", "# " .. text_helpers.plain(title), "" }
end

return M
